UPDATE `ContenidoPagina` SET `datos` = JSON_SET(`datos`, '$.bloques', JSON_ARRAY(JSON_OBJECT('tipo', 'fotoFija', 'titulo', '', 'pasos', JSON_ARRAY(
    JSON_OBJECT('titulo', 'Patrimonio y devoción', 'texto', 'El trono de Nuestra Señora de los Desamparados es una de las piezas más destacadas del patrimonio artístico y devocional del Grupo Parroquial. Diseñado para resaltar la belleza de la Sagrada Titular, combina la solidez de la ebanistería con el brillo de los metales, los bordados y las flores que lo adornan en su salida procesional.', 'foto', JSON_OBJECT('url', '/images/trono-candeleria.webp', 'alt', 'El trono de la Virgen, entre la candelería', 'pie', 'El trono')),
    JSON_OBJECT('titulo', 'Un conjunto armonioso', 'texto', 'Cada detalle del trono ha sido pensado para crear un conjunto armonioso que acompañe la imagen de la Virgen. Sus líneas, inspiradas en la tradición cofrade malagueña, se enriquecen con apliques dorados, lámparas de cristal y un exorno floral que varía cada año para vestir de manera única el paso de palio.', 'foto', JSON_OBJECT('url', '/images/trono-cera.webp', 'alt', 'Cirios y flores blancas del exorno del trono', 'pie', 'Cera y flor')),
    JSON_OBJECT('titulo', 'El andar de la Virgen', 'texto', 'El trono es portado por una cuadrilla de costaleros que, con esfuerzo y devoción, hacen posible que la Virgen avance entre el pueblo. Su andar pausado y solemne marca el ritmo de la procesión, generando momentos de gran emoción en cada una de las calles que recorre.', 'foto', JSON_OBJECT('url', '/images/trono-varales.webp', 'alt', 'Los portadores, en fila junto al trono', 'pie', 'Bajo los varales')),
    JSON_OBJECT('titulo', 'La comitiva', 'texto', 'Alrededor del trono se organizan los cargos de la procesión, los hermanos de luz y la música, configurando una comitiva que honra a la Sagrada Titular y que expresa la identidad propia del Grupo Parroquial en el Sábado de Pasión.', 'foto', JSON_OBJECT('url', '/images/trono-comitiva.webp', 'alt', 'El trono avanza entre ciriales y el público', 'pie', 'La comitiva'))))))
WHERE `slug` = 'trono' AND JSON_LENGTH(`datos`, '$.bloques') = 1
  AND JSON_UNQUOTE(JSON_EXTRACT(`datos`, '$.bloques[0].tipo')) = 'texto'
  AND JSON_UNQUOTE(JSON_EXTRACT(`datos`, '$.bloques[0].html')) LIKE '%El trono de Nuestra Señora de los Desamparados es una de las piezas%';
